namespace ShatterGuards {
static bool Equal(const void* a,const void* b,unsigned int n){const unsigned char* p=(const unsigned char*)a,*q=(const unsigned char*)b;for(unsigned int i=0;i<n;i++)if(p[i]!=q[i])return false;return true;}
static unsigned int Word(const void* p){unsigned int n;memcpy(&n,p,4);return n;}
static float Bits(unsigned int bits){float n;memcpy(&n,&bits,4);return n;}
static bool Empty(const NativeShatter::Payload& p){return !p.data&&!p.size&&!p.polygons&&!p.corners;}
static bool Rejected(NativeShatter::Payload& p,const NativeShatter::Polygon* in,unsigned int count,const WorldText::Vec3& center,const NativeShatter::Settings& s){return !p.Build(in,count,center,s)&&Empty(p)&&p.error&&p.error[0];}
static bool SourceEmpty(const NativeShatter::Builder& b){return !b.records&&!b.registryBindings&&!b.details&&!b.bindings&&!b.count&&!b.bindingCount&&!b.totalPolygons&&!b.totalCorners&&!b.totalBytes;}
static bool SourceRejected(NativeShatter::Builder& b,const NativePreparedRenderScene::Context& scene,const NativeShatter::Settings& s,unsigned int node=0xffffffffu){return !b.Build(scene,s)&&SourceEmpty(b)&&b.error==b.diagnostic&&b.error&&b.error[0]&&b.errorNode==node;}
static PrefabScene::Property* Property(PrefabScene::Node& n,const char* name){for(PrefabScene::Property* p=n.properties;p;p=p->next)if(GameClassMetadata::Exact(p->name,name))return p;return 0;}
static bool Put(HANDLE f,const void* p,unsigned int n){DWORD done=0;return !n||(WriteFile(f,p,n,&done,0)&&done==n);}
}
